import React from 'react';
import { Link } from 'react-router-dom';

function Home() {
  return (
    <div style={{ fontFamily: 'Arial, sans-serif' }}>
      <section
        style={{
          background: '#173F35',
          color: 'white',
          padding: '70px 25px',
          textAlign: 'center',
        }}
      >
        <h1>Welcome to CraftLanka</h1>

        <p>
          Discover authentic Sri Lankan handmade crafts
          and support local artisans.
        </p>

        <Link
          to="/products"
          style={{
            display: 'inline-block',
            background: '#D9A441',
            color: '#173F35',
            padding: '12px 24px',
            borderRadius: '6px',
            textDecoration: 'none',
            fontWeight: 'bold',
          }}
        >
          Explore Crafts
        </Link>
      </section>
    </div>
  );
}

export default Home;
